    valor_liquido NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    valor_total_retencoes NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    status_conciliacao VARCHAR(40) DEFAULT 'CONCILIADO',
    xml_storage_path TEXT,
