GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA iam TO supreme_iam;

GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA iam TO supreme_iam;

DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'iam' LOOP EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', 'iam', t.tablename); EXECUTE format('DROP POLICY IF EXISTS supreme_backend ON %I.%I', 'iam', t.tablename); EXECUTE format('CREATE POLICY supreme_backend ON %I.%I TO %I USING (true) WITH CHECK (true)', 'iam', t.tablename, 'supreme_iam'); END LOOP; END $$;

