CREATE OR REPLACE FUNCTION iam.prevent_audit_log_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $$ BEGIN RAISE EXCEPTION 'Audit logs are append-only.'; END; $$;

REVOKE ALL ON FUNCTION iam.prevent_audit_log_mutation() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_audit_logs_immutable ON iam.audit_logs;

CREATE TRIGGER trg_audit_logs_immutable BEFORE UPDATE OR DELETE ON iam.audit_logs FOR EACH ROW EXECUTE FUNCTION iam.prevent_audit_log_mutation();

